import java.io.BufferedReader
import java.io.InputStreamReader
import java.util.StringTokenizer

private const val MOD = 998244353L

private fun modPow(baseValue: Long, exponentValue: Long): Long {
    var base = baseValue
    var exponent = exponentValue
    var result = 1L
    while (exponent > 0) {
        if ((exponent and 1L) != 0L) result = result * base % MOD
        base = base * base % MOD
        exponent = exponent shr 1
    }
    return result
}

fun main() {
    val br = BufferedReader(InputStreamReader(System.`in`))
    val st = StringTokenizer(br.readLine())
    val p = st.nextToken().toInt()
    val s = st.nextToken().toInt()
    val r = st.nextToken().toInt()

    val maxN = s + p + 5
    val fact = LongArray(maxN)
    val invFact = LongArray(maxN)

    fact[0] = 1L
    for (i in 1 until maxN) {
        fact[i] = fact[i - 1] * i % MOD
    }

    invFact[maxN - 1] = modPow(fact[maxN - 1], MOD - 2)
    for (i in maxN - 1 downTo 1) {
        invFact[i - 1] = invFact[i] * i % MOD
    }

    fun combination(n: Int, k: Int): Long {
        if (n < 0 || k < 0 || k > n) return 0L
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD
    }

    val allCompositions = combination(s + p - 1, p - 1)

    var bounded = 0L
    if (r > 0) {
        val limit = minOf(p, s / r)
        for (j in 0..limit) {
            val term = combination(p, j) *
                    combination(s - j * r + p - 1, p - 1) % MOD
            bounded = if (j % 2 == 0) {
                (bounded + term) % MOD
            } else {
                (bounded - term + MOD) % MOD
            }
        }
    }

    val winningWeight = (allCompositions - bounded + MOD) % MOD
    val stateCount = combination(s - r + p - 1, p - 1)
    val denominator = p.toLong() * stateCount % MOD
    val answer = winningWeight * modPow(denominator, MOD - 2) % MOD

    println(answer)
}

